#!/usr/bin/env python3
"""Fail when a change edits a generated file that no patch record names.

Usage: python3 scripts/check_patches.py <base-ref>

A file whose first lines carry the `Generated by CLI Printing Press` header is
overwritten by a reprint, so an edit to it survives only when a record in
<cli-dir>/.printing-press-patches/ names its path (relative to the CLI dir).
Files added by the change (a new CLI, a new generated command) are not edits.
A reprint rewrites every generated file on purpose: CI skips this check on a
pull request labelled `reprint`.
"""

import os
import subprocess
import sys

HEADER = "Generated by CLI Printing Press"


def git(*args):
    return subprocess.run(["git", *args], capture_output=True, text=True, check=True).stdout


def is_generated(path):
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            return any(HEADER in f.readline() for _ in range(3))
    except OSError:
        return False


def records(cli_dir):
    folder = os.path.join(cli_dir, ".printing-press-patches")
    if not os.path.isdir(folder):
        return ""
    return "\n".join(open(os.path.join(folder, n), encoding="utf-8").read()
                     for n in sorted(os.listdir(folder)) if n.endswith(".md"))


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    modified = git("diff", "--name-only", "--diff-filter=M", f"{sys.argv[1]}...HEAD").split()
    missing = []
    for path in modified:
        cli_dir, sep, rel = path.partition("/")
        if not sep or not os.path.exists(os.path.join(cli_dir, "go.mod")) or not is_generated(path):
            continue
        if rel not in records(cli_dir):
            missing.append(path)
    for path in missing:
        print(f"{path}: generated file edited; name it in a record under "
              f"{path.split('/')[0]}/.printing-press-patches/")
    sys.exit(1 if missing else 0)


if __name__ == "__main__":
    main()
